def is_abundant(n):
    """
    This function checks if a number is abundant.
    """
    # Calculate the sum of divisors
    sum_divisors = 0
    for i in range(1, n):
        if n % i == 0:
            sum_divisors += i

    # Check if the sum of divisors is greater than the number
    if sum_divisors > n:
        return True
    else:
        return False
